) as c(name, slug, department, region, lng, lat, structure)
where not exists (
  select 1 from public.spots s
  where ST_DWithin(
    s.geom,
    ST_SetSRID(ST_MakePoint(c.lng::double precision, c.lat::double precision), 4326)::geography,
    150
  )
);

commit;
